{"source": "def investigate(context, acquire):
    hist = acquire("history")

    def simulate(put_mode, trig, chan, actions):
        committed = {}
        tmain = None
        tother = None
        changes_main = 0
        total_main = 0
        total_other = 0
        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                if conn == "main":
                    tmain = {}
                else:
                    tother = {}
            elif op == "commit":
                if conn == "main":
                    if tmain is not None:
                        for k, v in tmain.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        tmain = None
                else:
                    if tother is not None:
                        for k, v in tother.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        tother = None
            elif op == "rollback":
                if conn == "main":
                    tmain = None
                else:
                    tother = None
            elif op == "put":
                key = act.get("key")
                val = act.get("value")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                if buf is not None:
                    if key in buf:
                        exists = buf[key] is not None
                    else:
                        exists = key in committed
                else:
                    exists = key in committed
                changed = 0
                if put_mode == "ignore":
                    if not exists:
                        if buf is not None:
                            buf[key] = val
                        else:
                            committed[key] = val
                        changed = 1
                elif put_mode == "replace":
                    if buf is not None:
                        buf[key] = val
                    else:
                        committed[key] = val
                    changed = 1
                else:
                    if buf is not None:
                        buf[key] = val
                    else:
                        committed[key] = val
                    changed = 1
                if changed:
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
                    if trig == "after_insert" and not exists:
                        if conn == "main":
                            total_main += 1
                        else:
                            total_other += 1
            elif op == "update":
                key = act.get("key")
                val = act.get("value")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                if buf is not None:
                    if key in buf:
                        exists = buf[key] is not None
                    else:
                        exists = key in committed
                else:
                    exists = key in committed
                if exists:
                    if buf is not None:
                        buf[key] = val
                    else:
                        committed[key] = val
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
            elif op == "delete":
                key = act.get("key")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                if buf is not None:
                    if key in buf:
                        exists = buf[key] is not None
                    else:
                        exists = key in committed
                else:
                    exists = key in committed
                if exists:
                    if buf is not None:
                        buf[key] = None
                    else:
                        del committed[key]
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
        if chan == "changes":
            return changes_main
        elif chan == "total_main":
            return total_main
        else:
            return total_main + total_other

    def committed_state(actions):
        committed = {}
        tmain = None
        tother = None
        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                if conn == "main":
                    tmain = {}
                else:
                    tother = {}
            elif op == "commit":
                if conn == "main":
                    if tmain is not None:
                        for k, v in tmain.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        tmain = None
                else:
                    if tother is not None:
                        for k, v in tother.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        tother = None
            elif op == "rollback":
                if conn == "main":
                    tmain = None
                else:
                    tother = None
            elif op == "put":
                key = act.get("key")
                val = act.get("value")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                if buf is not None:
                    buf[key] = val
                else:
                    committed[key] = val
            elif op == "update":
                key = act.get("key")
                val = act.get("value")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                if buf is not None:
                    buf[key] = val
                else:
                    committed[key] = val
            elif op == "delete":
                key = act.get("key")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                if buf is not None:
                    buf[key] = None
                else:
                    if key in committed:
                        del committed[key]
        return committed

    candidates = []
    for put_mode in ["ignore", "replace", "upsert"]:
        for trig in ["none", "after_insert"]:
            for chan in ["changes", "total_main", "total_both"]:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    if simulate(put_mode, trig, chan, acts) != obs.get("channel"):
                        ok = False
                        break
                    st = committed_state(acts)
                    if len(st) != obs.get("committed_count"):
                        ok = False
                        break
                    if sum(st.values()) != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, trig, chan))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])

    vals = set()
    for put_mode, trig, chan in candidates:
        if goal == "channel":
            vals.add(simulate(put_mode, trig, chan, actions))
        elif goal == "committed_count":
            vals.add(len(committed_state(actions)))
        elif goal == "committed_sum":
            vals.add(sum(committed_state(actions).values()))
        else:
            return {"value": None, "unresolved": True}

    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}
